package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.DetachedVO;

@RequiredArgsConstructor
public class DetachedValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<DetachedVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param detached
   * @return
   */
  public T detached(DetachedVO detached) {
    this.value = Optional.of(detached);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param detached
   * @return
   */
  public T detached(Optional<DetachedVO> detached) {
    this.value = detached;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param detached
   * @return
   */
  public T detached(Boolean detached) {
    this.value = Optional.of(DetachedVO.from(detached));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Boolean> getDetached() {
    return value.map(DetachedVO::isDetached);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<DetachedVO> getDetachedValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public DetachedVO readDetached(final Optional<ObservedSource> original,
      final ConstraintFailList fails) {
    DetachedVO result = value.orElse(original.map(ObservedSource::getDetachedValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "detached", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetDetached() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetDetachedIfMatches(final String field) {
    if ("detached".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
